// Generated by Cypress Author on 2026-10-19
//
// PAR 01 · PAR 02 · PAR 03 (P0/P1) — Plano_de_Testes_QA_MatchWallet.md §9.2.
// A validação de continuidade das faixas existe no front (e deve existir também no servidor — ver
// e2e/real/autorizacao.cy.ts para a permissão). Aqui garantimos que faixa inválida nunca gera PUT.

const CONFIG = {
  versao: 1,
  escalaMaxima: 60,
  faixas: [
    { perfil: 'CONSERVADOR', min: 0, max: 17 },
    { perfil: 'MODERADO', min: 18, max: 32 },
    { perfil: 'ARROJADO', min: 33, max: 46 },
    { perfil: 'SOFISTICADO', min: 47, max: 60 },
  ],
  criadoEm: '2026-01-01T00:00:00.000Z',
}

const campo = (tipo: 'mínima' | 'máxima', perfil: string) =>
  `[aria-label="Pontuação ${tipo} do perfil ${perfil}"]`

describe('Plano QA · Parâmetros de suitability (admin)', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubSessao('admin')
    cy.stubApi('GET', '/configuracoes/suitability', CONFIG, 'config')
    cy.stubApi('PUT', '/configuracoes/suitability', { ...CONFIG, versao: 2 }, 'salvar')

    cy.visit('/admin/configuracoes')
    cy.wait('@config')
  })

  it('PAR 01 · edita e cancela → faixas voltam ao valor salvo e nada é enviado', () => {
    cy.contains('0 a 17 pontos').should('be.visible')

    cy.get('[data-cy="faixas-editar"]').click()
    cy.get('[data-cy="faixas-salvar"]').should('be.disabled')
    cy.get(campo('máxima', 'Conservador')).clear().type('20')
    cy.get('[data-cy="faixas-cancelar"]').click()

    cy.contains('0 a 17 pontos').should('be.visible')
    cy.get('@salvar.all').should('have.length', 0)
  })

  // Cada linha: o que é digitado, o campo, e um trecho da mensagem esperada.
  const INVALIDAS = [
    {
      caso: 'lacuna (Conservador termina em 15, Moderado começa em 18)',
      campo: campo('máxima', 'Conservador'),
      valor: '15',
      mensagem: 'lacuna ou sobreposição',
    },
    {
      caso: 'sobreposição (Conservador termina em 18, Moderado começa em 18)',
      campo: campo('máxima', 'Conservador'),
      valor: '18',
      mensagem: 'lacuna ou sobreposição',
    },
    {
      caso: 'mínimo maior que o máximo',
      campo: campo('mínima', 'Moderado'),
      valor: '40',
      mensagem: 'precisa ser maior ou igual',
    },
    {
      caso: 'última faixa acima da escala (61)',
      campo: campo('máxima', 'Sofisticado'),
      valor: '61',
      mensagem: 'terminar em 60',
    },
    {
      caso: 'primeira faixa fora do zero',
      campo: campo('mínima', 'Conservador'),
      valor: '1',
      mensagem: 'começar em 0',
    },
  ]

  for (const { caso, campo: seletor, valor, mensagem } of INVALIDAS) {
    it(`PAR 02 · ${caso} → alerta o problema e bloqueia o Salvar`, () => {
      cy.get('[data-cy="faixas-editar"]').click()
      cy.get(seletor).clear().type(valor)

      cy.get('[data-cy="faixas-status"]').should('contain.text', mensagem)
      cy.get('[data-cy="faixas-salvar"]').should('be.disabled')
      cy.get('@salvar.all').should('have.length', 0)
    })
  }

  it('PAR 02 · limite vazio → pede para preencher todos os números e bloqueia o Salvar', () => {
    cy.get('[data-cy="faixas-editar"]').click()
    cy.get(campo('máxima', 'Conservador')).clear()

    cy.get('[data-cy="faixas-status"]').should('contain.text', 'Preencha todos os limites')
    cy.get('[data-cy="faixas-salvar"]').should('be.disabled')
  })

  it('PAR 03 · move a fronteira mantendo 0–60 contínuo → envia as 4 faixas e confirma o salvamento', () => {
    cy.get('[data-cy="faixas-editar"]').click()
    cy.get(campo('máxima', 'Conservador')).clear().type('20')
    cy.get(campo('mínima', 'Moderado')).clear().type('21')

    cy.get('[data-cy="faixas-status"]').should('contain.text', 'sem lacuna nem sobreposição')
    cy.get('[data-cy="faixas-salvar"]').should('be.enabled').click()

    cy.wait('@salvar')
      .its('request.body')
      .should('deep.equal', {
        escalaMaxima: 60,
        faixas: [
          { perfil: 'CONSERVADOR', min: 0, max: 20 },
          { perfil: 'MODERADO', min: 21, max: 32 },
          { perfil: 'ARROJADO', min: 33, max: 46 },
          { perfil: 'SOFISTICADO', min: 47, max: 60 },
        ],
      })
    cy.contains('Parâmetros de suitability salvos').should('be.visible')
  })
})

export {}
